def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的族群分布、文化景觀與社會資料推理能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的群體、空間、時間、遷移、制度與當事人觀點。", f"整理證據：分開統計分布、歷史形成、文化表現與權力關係；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」能避免把族群簡化成固定標籤。", "排除誘答：檢查是否只看人數、單一街區、官方宣傳或可見符號，並找出被忽略的聲音與脈絡。", "結論回查：確認空間尺度、分類限制與當事人資料一致；換群體或地區時重新判讀。"]
    return {"id": f"question-social-content-geo-ad-iv-3-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ad-iv-3"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫多元族群與文化情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ad-iv-3", "examPatternRefs": refs, "solutionStrategy": "先比較族群空間資料與歷史脈絡，再納入遷移、制度與當事人觀點，最後檢查分類、尺度與文化權力限制。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ad-iv-3-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
